import type { WeatherInfo } from "./types";

// open-meteo WMO weather_code → 中文描述
const WMO: Record<number, string> = {
  0: "晴",
  1: "晴间多云",
  2: "多云",
  3: "阴",
  45: "雾",
  48: "雾凇",
  51: "毛毛雨",
  53: "毛毛雨",
  55: "毛毛雨",
  56: "冻毛毛雨",
  57: "冻毛毛雨",
  61: "小雨",
  63: "中雨",
  65: "大雨",
  66: "冻雨",
  67: "冻雨",
  71: "小雪",
  73: "中雪",
  75: "大雪",
  77: "霰",
  80: "阵雨",
  81: "阵雨",
  82: "强阵雨",
  85: "阵雪",
  86: "强阵雪",
  95: "雷阵雨",
  96: "雷阵雨夹冰雹",
  99: "强雷阵雨夹冰雹",
};

function desc(code: number): string {
  return WMO[code] ?? "未知";
}

/** 经纬度 → 当前天气（open-meteo，免 key） */
export async function fetchWeather(lat: number, lon: number): Promise<WeatherInfo | null> {
  const url =
    `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
    `&current=temperature_2m,weather_code,is_day`;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const cur = data?.current;
    if (!cur) return null;
    return {
      tempC: Math.round(cur.temperature_2m),
      code: cur.weather_code,
      desc: desc(cur.weather_code),
      isDay: cur.is_day === 1,
    };
  } catch {
    return null;
  }
}

/** 基于浏览器定位获取天气，失败返回 null（静默降级） */
export function getWeatherByGeo(): Promise<WeatherInfo | null> {
  return new Promise((resolve) => {
    if (!("geolocation" in navigator)) return resolve(null);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const w = await fetchWeather(pos.coords.latitude, pos.coords.longitude);
        resolve(w);
      },
      () => resolve(null),
      { timeout: 6000, maximumAge: 600000 },
    );
  });
}
