import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import Rule from "@/components/ui/Rule";
import MoodCurve from "@/components/history/MoodCurve";
import MoodTimeline from "@/components/history/MoodTimeline";
import { loadHistory, clearHistory } from "@/lib/storage";
import type { MoodEntry } from "@/lib/types";

export default function History() {
  const [entries, setEntries] = useState<MoodEntry[]>([]);

  useEffect(() => {
    setEntries(loadHistory());
  }, []);

  const handleClear = () => {
    clearHistory();
    setEntries([]);
  };

  const empty = entries.length === 0;

  return (
    <div className="flex flex-col">
      <span className="label-cap">心情轨迹 · THE TRACE</span>
      <h2 className="display-lg mt-3">这些天，你的心情</h2>
      <p className="prose-read mt-4 max-w-measure">
        每一次「调味」都会被记下。日子是有痕迹的，回头看，你会发现自己走过的曲线。
      </p>

      <Rule className="mt-10" />

      {empty ? (
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7 }}
          className="py-20 text-center"
        >
          <p
            className="mx-auto max-w-measure"
            style={{ fontFamily: "var(--font-display)", fontSize: "1.4rem", lineHeight: 1.8, color: "var(--ink-soft)" }}
          >
            还没有轨迹。
            <br />
            去今日写下心情，开始第一笔。
          </p>
          <div className="mt-8">
            <Link to="/" className="btn-ink">
              回到今日
            </Link>
          </div>
        </motion.div>
      ) : (
        <div className="flex flex-col gap-12 py-10">
          <section>
            <div className="flex items-baseline justify-between mb-6">
              <span className="label-cap">情绪曲线 · MOOD CURVE</span>
              <span className="italic-accent text-sm">{entries.length} 笔记录</span>
            </div>
            <MoodCurve entries={entries} />
          </section>

          <Rule />

          <section>
            <div className="flex items-baseline justify-between mb-2">
              <span className="label-cap">心情手记 · JOURNAL</span>
              <button
                type="button"
                onClick={handleClear}
                className="link-grow text-sm text-ink-mute hover:text-ink"
              >
                清空轨迹
              </button>
            </div>
            <MoodTimeline entries={entries} />
          </section>
        </div>
      )}
    </div>
  );
}
