import { motion } from "framer-motion";
import SectionNumber from "@/components/ui/SectionNumber";
import Rule from "@/components/ui/Rule";
import StreamText from "@/components/ui/StreamText";
import type { Recipe } from "@/lib/types";
import type { StreamStatus } from "@/hooks/useStreamText";

interface RecipeViewProps {
  recipe: Recipe;
  rawText: string;
  status: StreamStatus;
  isMock: boolean;
}

export default function RecipeView({ recipe, status, isMock }: RecipeViewProps) {
  const streaming = status === "loading";
  return (
    <motion.section
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7, ease: [0.22, 0.61, 0.36, 1] }}
      className="mt-12"
    >
      <div className="flex items-center justify-between">
        <span className="label-cap">今日菜谱 · FROM THE FRIDGE</span>
        {isMock && (
          <span className="label-cap" style={{ color: "var(--accent-ink)" }}>
            离线示例
          </span>
        )}
      </div>

      <div className="grid grid-cols-12 gap-x-6 gap-y-4 pt-6">
        <header className="col-span-12 md:col-span-3">
          <SectionNumber num="01" label="味 · TASTE" />
        </header>
        <div className="col-span-12 md:col-span-9 md:pl-6 md:border-l md:border-rule">
          <h3 className="display-lg">
            {recipe.title ? (
              <>
                <span className="italic-accent mr-1" style={{ fontSize: "0.7em" }}>《</span>
                {recipe.title}
                <span className="italic-accent ml-1" style={{ fontSize: "0.7em" }}>》</span>
              </>
            ) : (
              streaming && <span className="caret" aria-hidden />
            )}
          </h3>

          {recipe.rationale && (
            <div className="border-l-2 pl-4 my-4" style={{ borderColor: "var(--accent)" }}>
              <div className="label-cap mb-1" style={{ color: "var(--accent-ink)" }}>
                为什么用它
              </div>
              <p className="prose-read !max-w-none">
                <StreamText text={recipe.rationale} streaming={streaming && !recipe.rationale} />
              </p>
            </div>
          )}

          {recipe.ingredients.length > 0 && (
            <div className="mt-5">
              <span className="label-cap">食材</span>
              <ul className="mt-2 space-y-1">
                {recipe.ingredients.map((ing, i) => (
                  <li key={i} className="flex gap-3 text-ink-soft">
                    <span className="section-num" style={{ minWidth: "1.5ch" }}>
                      —
                    </span>
                    <span>{ing}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {recipe.steps.length > 0 && (
            <div className="mt-5">
              <span className="label-cap">做法</span>
              <ol className="mt-2 space-y-2">
                {recipe.steps.map((step, i) => (
                  <li key={i} className="flex gap-3 text-ink-soft" style={{ lineHeight: 1.75 }}>
                    <span className="section-num" style={{ minWidth: "1.5ch" }}>
                      {String(i + 1).padStart(2, "0")}
                    </span>
                    <span>{step}</span>
                  </li>
                ))}
                {streaming && (
                  <li className="flex gap-3">
                    <span className="section-num" style={{ minWidth: "1.5ch" }}>
                      {String(recipe.steps.length + 1).padStart(2, "0")}
                    </span>
                    <span className="caret" aria-hidden />
                  </li>
                )}
              </ol>
            </div>
          )}

          {recipe.tip && (
            <div className="mt-6 pt-4" style={{ borderTop: "1px solid var(--rule)" }}>
              <span className="label-cap">小贴士</span>
              <p className="prose-read !max-w-none mt-1">
                <StreamText text={recipe.tip} streaming={streaming && !recipe.tip} />
              </p>
            </div>
          )}
        </div>
      </div>
      <Rule className="mt-8" />
    </motion.section>
  );
}
