import { useMemo, useState } from "react";
import { motion } from "framer-motion";
import DateLine from "@/components/layout/DateLine";
import MoodCapture from "@/components/mood/MoodCapture";
import PlanSpread from "@/components/plan/PlanSpread";
import Rule from "@/components/ui/Rule";
import { useStreamText } from "@/hooks/useStreamText";
import { useWeather } from "@/hooks/useWeather";
import { useAccent } from "@/store/useAccent";
import { buildTodayMessages } from "@/lib/prompts";
import { mockTodayText } from "@/lib/mock";
import { parseTodayPlan } from "@/lib/parse";
import { saveEntry } from "@/lib/storage";
import type { MoodContext } from "@/lib/types";

export default function Today() {
  const { weather } = useWeather();
  const moodValue = useAccent((s) => s.moodValue);
  const palette = useAccent((s) => s.palette);
  const [ctx, setCtx] = useState<MoodContext | null>(null);
  const [saved, setSaved] = useState(false);

  const { text, status, isMock, run, reset } = useStreamText(
    () => (ctx ? buildTodayMessages(ctx) : null),
    () => mockTodayText(ctx ?? { moodText: "", moodValue }),
    [ctx],
  );

  const plan = useMemo(() => parseTodayPlan(text), [text]);

  const handleSubmit = (c: MoodContext) => {
    setCtx(c);
    setSaved(false);
    // 等 ctx 写入后再触发（buildRef 读取最新 ctx）
    setTimeout(() => run(), 0);
  };

  const handleReset = () => {
    reset();
    setCtx(null);
    setSaved(false);
  };

  const handleSave = () => {
    if (!ctx) return;
    const entry = {
      id:
        typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : String(Date.now()),
      date: new Date().toISOString(),
      moodText: ctx.moodText,
      moodValue: ctx.moodValue,
      accent: palette.accent,
      summary: plan.summary,
    };
    saveEntry(entry);
    setSaved(true);
  };

  const idle = status === "idle";

  return (
    <div className="flex flex-col">
      {/* Hero */}
      <DateLine weather={weather} />
      <p className="prose-read mt-6 max-w-measure">
        把今天认真调一味。告诉调味师你现在的心情，它为你配出今日的{" "}
        <span style={{ color: "var(--accent-ink)" }}>味、影、行、息</span>
        ——每一味都附上「为什么是它」。
      </p>

      <Rule className="mt-10" />

      {/* 心情捕获 / 重新调味 */}
      {idle ? (
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="py-10"
        >
          <MoodCapture weather={weather} onSubmit={handleSubmit} loading={false} />
        </motion.div>
      ) : (
        <div className="py-6 flex items-center justify-between">
          <span className="label-cap">
            {ctx?.moodText ? `「${ctx.moodText}」` : "今日心情"}
          </span>
          <button type="button" className="btn-ink" onClick={handleReset}>
            换个心情，再调一次
          </button>
        </div>
      )}

      {/* 方案 */}
      {!idle && (text || status === "loading") && (
        <PlanSpread
          plan={plan}
          status={status}
          isMock={isMock}
          onSave={handleSave}
          saved={saved}
        />
      )}
    </div>
  );
}
