import { useState } from "react";
import Tag from "@/components/ui/Tag";
import { X } from "lucide-react";

interface FridgeInputProps {
  onSubmit: (ingredients: string[], opts: { preference?: string; minutes?: number; level?: string }) => void;
  loading?: boolean;
}

export default function FridgeInput({ onSubmit, loading }: FridgeInputProps) {
  const [items, setItems] = useState<string[]>([]);
  const [draft, setDraft] = useState("");
  const [preference, setPreference] = useState("");
  const [minutes, setMinutes] = useState<number | undefined>(undefined);
  const [level, setLevel] = useState<string | undefined>(undefined);

  const add = () => {
    const t = draft.trim();
    if (!t) return;
    if (items.includes(t)) return;
    setItems([...items, t]);
    setDraft("");
  };

  const remove = (i: string) => setItems(items.filter((x) => x !== i));

  return (
    <div className="flex flex-col gap-8">
      <div>
        <label className="label-cap" htmlFor="fridge-input">
          冰箱里有什么
        </label>
        <div className="mt-3 flex flex-wrap items-center gap-2 border-b border-rule pb-3">
          {items.map((i) => (
            <span
              key={i}
              className="inline-flex items-center gap-1.5 px-2.5 py-1 text-sm border border-accent text-ink bg-accent-soft"
              style={{ borderRadius: 2 }}
            >
              {i}
              <button
                type="button"
                onClick={() => remove(i)}
                className="text-ink-mute hover:text-ink"
                aria-label={`移除 ${i}`}
              >
                <X size={12} strokeWidth={2} />
              </button>
            </span>
          ))}
          <input
            id="fridge-input"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                add();
              }
              if (e.key === "Backspace" && !draft && items.length) {
                remove(items[items.length - 1]);
              }
            }}
            placeholder={items.length ? "" : "番茄、鸡蛋、隔夜饭……回车添加"}
            className="flex-1 min-w-[12ch] bg-transparent outline-none text-base"
            style={{ fontFamily: "var(--font-display)" }}
          />
        </div>
      </div>

      <div className="grid sm:grid-cols-2 gap-8">
        <div>
          <span className="label-cap">口味偏好（可选）</span>
          <input
            value={preference}
            onChange={(e) => setPreference(e.target.value)}
            placeholder="清淡 / 酸辣 / 下饭……"
            className="input-line w-full mt-3 py-2"
          />
        </div>
        <div>
          <span className="label-cap">希望多久做好</span>
          <div className="flex gap-2 mt-3">
            {[
              { v: 15, l: "15 分钟" },
              { v: 30, l: "30 分钟" },
              { v: 60, l: "一小时" },
            ].map((o) => (
              <Tag
                key={o.v}
                active={minutes === o.v}
                onClick={() => setMinutes(minutes === o.v ? undefined : o.v)}
              >
                {o.l}
              </Tag>
            ))}
          </div>
        </div>
      </div>

      <div className="flex items-center gap-3">
        <span className="label-cap w-10">厨艺</span>
        <Tag active={level === "新手"} onClick={() => setLevel(level === "新手" ? undefined : "新手")}>
          新手
        </Tag>
        <Tag active={level === "熟练"} onClick={() => setLevel(level === "熟练" ? undefined : "熟练")}>
          熟练
        </Tag>
      </div>

      <div>
        <button
          type="button"
          className="btn-ink"
          onClick={() => onSubmit(items, { preference: preference.trim() || undefined, minutes, level })}
          disabled={loading || items.length === 0}
        >
          配一道菜
          <span className="italic-accent" style={{ fontSize: "0.8rem" }}>
            from the fridge
          </span>
        </button>
      </div>
    </div>
  );
}
