// OpenAI 兼容流式客户端
// 兼容豆包(Volcengine Ark) / 通义千问 / DeepSeek / OpenAI —— 均支持 /chat/completions (stream)

export interface LLMConfig {
  apiKey: string;
  baseUrl: string;
  model: string;
}

export function getLLMConfig(): LLMConfig | null {
  const apiKey = import.meta.env.VITE_LLM_API_KEY?.trim();
  const baseUrl = import.meta.env.VITE_LLM_BASE_URL?.trim();
  const model = import.meta.env.VITE_LLM_MODEL?.trim();
  if (!apiKey || !baseUrl || !model) return null;
  return { apiKey, baseUrl, model };
}

export function hasLLM(): boolean {
  return getLLMConfig() !== null;
}

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

/**
 * 流式对话补全。逐块 yield 增量文本。
 * 失败（无配置 / 网络错误 / 非 2xx）抛出，调用方回退到 mock。
 */
export async function* streamChat(
  messages: ChatMessage[],
  signal?: AbortSignal,
): AsyncGenerator<string, void, unknown> {
  const cfg = getLLMConfig();
  if (!cfg) throw new Error("no-llm-config");

  const res = await fetch(`${cfg.baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${cfg.apiKey}`,
    },
    body: JSON.stringify({
      model: cfg.model,
      messages,
      stream: true,
      temperature: 0.85,
      max_tokens: 1600,
    }),
    signal,
  });

  if (!res.ok || !res.body) throw new Error(`llm-http-${res.status}`);

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || !trimmed.startsWith("data:")) continue;
      const data = trimmed.slice(5).trim();
      if (data === "[DONE]") return;
      try {
        const json = JSON.parse(data);
        const delta: string | undefined = json?.choices?.[0]?.delta?.content;
        if (delta) yield delta;
      } catch {
        // 跳过不完整的 JSON 行
      }
    }
  }
}
