import StreamText from "@/components/ui/StreamText";

interface RationaleProps {
  text: string;
  streaming?: boolean;
}

/** 「为什么是它」—— 调味师的灵魂：把推荐与情绪关联 */
export default function Rationale({ text, streaming }: RationaleProps) {
  if (!text && !streaming) return null;
  return (
    <div
      className="border-l-2 pl-4 my-4"
      style={{ borderColor: "var(--accent)" }}
    >
      <div className="label-cap mb-1" style={{ color: "var(--accent-ink)" }}>
        为什么是它
      </div>
      <p className="prose-read !max-w-none">
        <StreamText text={text} streaming={streaming} />
      </p>
    </div>
  );
}
