import { cn } from "@/lib/utils";

interface RuleProps {
  variant?: "default" | "accent";
  className?: string;
}

/** hairline 分隔线 —— 印刷感的来源，替代卡片边框与阴影 */
export default function Rule({ variant = "default", className }: RuleProps) {
  return (
    <hr
      className={cn(
        variant === "accent" ? "hairline-accent" : "hairline",
        className,
      )}
    />
  );
}
