import { cn } from "@/lib/utils";

interface TagProps {
  active?: boolean;
  onClick?: () => void;
  children: React.ReactNode;
}

/** 上下文标签：选中时以强调色描边/底，未选中为 hairline */
export default function Tag({ active, onClick, children }: TagProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "px-3 py-1 text-sm border transition-colors duration-500 ease-ink",
        active
          ? "border-accent text-ink bg-accent-soft"
          : "border-rule text-ink-mute hover:text-ink-soft hover:border-ink-mute",
      )}
      style={{ borderRadius: 2 }}
    >
      {children}
    </button>
  );
}
