import { motion } from "framer-motion";
import Rule from "@/components/ui/Rule";
import StreamText from "@/components/ui/StreamText";
import PlanSection from "./PlanSection";
import type { MoodPlan } from "@/lib/types";
import type { StreamStatus } from "@/hooks/useStreamText";

interface PlanSpreadProps {
  plan: MoodPlan;
  status: StreamStatus;
  isMock: boolean;
  onSave?: () => void;
  saved?: boolean;
}

export default function PlanSpread({ plan, status, isMock, onSave, saved }: PlanSpreadProps) {
  const summaryStreaming = status === "loading" && plan.sections.length === 0;
  const showSave = status === "done" && onSave;

  return (
    <motion.section
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.6 }}
      className="mt-16"
    >
      {/* 标头 */}
      <div className="flex items-center justify-between">
        <span className="label-cap">今日调味方案 · TODAY&rsquo;S SEASONING</span>
        {isMock && (
          <span className="label-cap" style={{ color: "var(--accent-ink)" }}>
            离线示例
          </span>
        )}
      </div>

      <h2 className="display-xl mt-3">今日，为你调味</h2>

      {/* 情绪总结 */}
      {(plan.summary || summaryStreaming) && (
        <p
          className="mt-6 text-xl"
          style={{ fontFamily: "var(--font-display)", lineHeight: 1.6, color: "var(--ink)" }}
        >
          <StreamText text={plan.summary} streaming={summaryStreaming} />
        </p>
      )}

      <Rule className="mt-10" />

      {/* 四节 */}
      <div>
        {plan.sections.map((s) => (
          <div key={s.key}>
            <PlanSection data={s} />
            <Rule />
          </div>
        ))}
      </div>

      {/* 仍在书写的提示 */}
      {status === "loading" && plan.sections.length > 0 && (
        <div className="py-6 label-cap flex items-center gap-3">
          <span className="caret" aria-hidden />
          调味师正在落笔……
        </div>
      )}

      {/* 保存到轨迹 */}
      {showSave && (
        <div className="mt-8">
          <button
            type="button"
            className="btn-ink"
            onClick={onSave}
            disabled={saved}
          >
            {saved ? "已收进轨迹" : "收进今日轨迹"}
          </button>
        </div>
      )}
    </motion.section>
  );
}
