import { useAccent } from "@/store/useAccent";

const TICKS = ["低落", "平静", "温柔", "喜悦"];

/** 心情光谱：hairline 轨道 + 强调色圆点，拖动时全局强调色实时漂移 */
export default function MoodSpectrum() {
  const moodValue = useAccent((s) => s.moodValue);
  const setMood = useAccent((s) => s.setMood);

  return (
    <div>
      <input
        type="range"
        min={0}
        max={100}
        value={moodValue}
        onChange={(e) => setMood(Number(e.target.value))}
        className="mood-range"
        aria-label="今天的心情光谱"
      />
      <div className="flex justify-between">
        {TICKS.map((t) => (
          <span key={t} className="label-cap">
            {t}
          </span>
        ))}
      </div>
    </div>
  );
}
