import { useState } from "react";
import MoodSpectrum from "./MoodSpectrum";
import ContextTags from "./ContextTags";
import { useAccent } from "@/store/useAccent";
import type { MoodContext } from "@/lib/types";

interface MoodCaptureProps {
  weather?: import("@/lib/types").WeatherInfo | null;
  onSubmit: (ctx: MoodContext) => void;
  loading?: boolean;
}

export default function MoodCapture({ weather, onSubmit, loading }: MoodCaptureProps) {
  const moodValue = useAccent((s) => s.moodValue);
  const [moodText, setMoodText] = useState("");
  const [alone, setAlone] = useState<boolean | undefined>(undefined);
  const [indoor, setIndoor] = useState<boolean | undefined>(undefined);
  const [canCook, setCanCook] = useState<boolean | undefined>(undefined);

  const submit = () => {
    onSubmit({
      moodText: moodText.trim(),
      moodValue,
      weather: weather ?? null,
      alone,
      indoor,
      canCook,
    });
  };

  return (
    <div className="flex flex-col gap-8">
      {/* 心情一句话 */}
      <div>
        <label className="label-cap" htmlFor="mood-text">
          用一句话形容你的今天
        </label>
        <textarea
          id="mood-text"
          value={moodText}
          onChange={(e) => setMoodText(e.target.value)}
          placeholder="比如：今天有点累，但想好好吃顿饭……"
          rows={2}
          className="input-line w-full mt-3 py-2 text-lg resize-none"
          style={{ fontFamily: "var(--font-display)", lineHeight: 1.7 }}
          onKeyDown={(e) => {
            if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) submit();
          }}
        />
      </div>

      {/* 心情光谱 */}
      <div>
        <span className="label-cap">心情光谱</span>
        <MoodSpectrum />
      </div>

      {/* 上下文 */}
      <div>
        <span className="label-cap mb-3 block">今天的处境（可选）</span>
        <ContextTags
          value={{ alone, indoor, canCook }}
          onChange={(p) => {
            if ("alone" in p) setAlone(p.alone);
            if ("indoor" in p) setIndoor(p.indoor);
            if ("canCook" in p) setCanCook(p.canCook);
          }}
        />
      </div>

      {/* 提交 */}
      <div>
        <button
          type="button"
          className="btn-ink"
          onClick={submit}
          disabled={loading}
        >
          为我调味
          <span className="italic-accent" style={{ fontSize: "0.8rem" }}>
            season my day
          </span>
        </button>
      </div>
    </div>
  );
}
