interface StreamTextProps {
  text: string;
  streaming?: boolean;
  className?: string;
}

/** 流式文本：保留换行，结尾呼吸光标 */
export default function StreamText({ text, streaming, className }: StreamTextProps) {
  return (
    <span className={className} style={{ whiteSpace: "pre-wrap" }}>
      {text}
      {streaming && <span className="caret" aria-hidden />}
    </span>
  );
}
