// 心情 → 强调色调色板
// 设计：4 个锚色对应 4 种心境，随心情值在锚色间线性插值（CSS 负责 800ms 过渡）
// 锚色取低饱和、有温度的「纸上调和」，避免一切荧光 / 渐变填充感

export interface MoodPalette {
  accent: string;
  accentSoft: string; // 12% 透明
  accentInk: string; // 加深 30%，用于强调色上的文字
  name: string;
}

interface Anchor {
  v: number;
  rgb: [number, number, number];
  name: string;
}

// 心情值 → 锚色
const ANCHORS: Anchor[] = [
  { v: 0, rgb: [107, 122, 138], name: "暮霭" }, // 低落：暮霭蓝灰
  { v: 38, rgb: [122, 139, 106], name: "鼠尾草" }, // 平静：鼠尾草绿
  { v: 66, rgb: [201, 139, 134], name: "暮粉" }, // 温柔：暮粉
  { v: 100, rgb: [200, 132, 58], name: "赭石" }, // 喜悦：赭石黄
];

function lerp(a: number, b: number, t: number): number {
  return Math.round(a + (b - a) * t);
}

function toHex(n: number): string {
  return n.toString(16).padStart(2, "0");
}

function rgbToHex(r: number, g: number, b: number): string {
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

function darken(r: number, g: number, b: number, amt: number): [number, number, number] {
  return [Math.round(r * (1 - amt)), Math.round(g * (1 - amt)), Math.round(b * (1 - amt))];
}

/** 根据心情值计算调色板 */
export function paletteForMood(value: number): MoodPalette {
  const v = Math.max(0, Math.min(100, value));
  let a = ANCHORS[0];
  let b = ANCHORS[ANCHORS.length - 1];
  for (let i = 0; i < ANCHORS.length - 1; i++) {
    if (v >= ANCHORS[i].v && v <= ANCHORS[i + 1].v) {
      a = ANCHORS[i];
      b = ANCHORS[i + 1];
      break;
    }
  }
  const span = b.v - a.v || 1;
  const t = (v - a.v) / span;
  const r = lerp(a.rgb[0], b.rgb[0], t);
  const g = lerp(a.rgb[1], b.rgb[1], t);
  const bl = lerp(a.rgb[2], b.rgb[2], t);
  const accent = rgbToHex(r, g, bl);
  const accentSoft = `rgba(${r}, ${g}, ${bl}, 0.12)`;
  const [dr, dg, db] = darken(r, g, bl, 0.32);
  const accentInk = rgbToHex(dr, dg, db);
  const name = t < 0.5 ? a.name : b.name;
  return { accent, accentSoft, accentInk, name };
}

/** 将调色板写入 :root CSS 变量 */
export function applyPalette(p: MoodPalette) {
  const root = document.documentElement;
  root.style.setProperty("--accent", p.accent);
  root.style.setProperty("--accent-soft", p.accentSoft);
  root.style.setProperty("--accent-ink", p.accentInk);
}
