import type { MoodPlan, PlanSection, SectionKey, Recipe, HealingPlan } from "./types";

// 通用：从正文里取 《...》 内的标题
function extractTitle(body: string): string {
  const m = body.match(/《([^》]*)》/);
  return m ? m[1].trim() : "";
}

// 通用：取「为什么是它——」或「为什么用它——」后的理由
function extractRationale(body: string): string {
  const m = body.match(/为什么是[它用]——\s*([^\n]*)/);
  return m ? m[1].trim() : "";
}

/** 取某行前缀之后到行尾的内容 */
function afterPrefix(body: string, prefix: RegExp): string {
  const m = body.match(prefix);
  return m ? m[1].trim() : "";
}

// ────────────────────────────────────────
// 今日调味方案
// ────────────────────────────────────────
const SECTION_DEFS: { key: SectionKey; label: string; marker: string }[] = [
  { key: "taste", label: "味 · TASTE", marker: "## 味" },
  { key: "watch", label: "影 · WATCH", marker: "## 影" },
  { key: "go", label: "行 · GO", marker: "## 行" },
  { key: "rest", label: "息 · REST", marker: "## 息" },
];

export function parseTodayPlan(text: string): MoodPlan {
  const marks = SECTION_DEFS.map((d) => ({ ...d, idx: text.indexOf(d.marker) }));

  const started = marks.filter((m) => m.idx >= 0);
  const firstIdx = started.length ? Math.min(...started.map((m) => m.idx)) : -1;
  const summary = (firstIdx >= 0 ? text.slice(0, firstIdx) : text).trim();

  const sections: PlanSection[] = [];
  for (let i = 0; i < SECTION_DEFS.length; i++) {
    const def = SECTION_DEFS[i];
    const idx = text.indexOf(def.marker);
    if (idx < 0) continue;
    const nlIdx = text.indexOf("\n", idx + def.marker.length);
    const bodyStart = nlIdx < 0 ? text.length : nlIdx + 1;
    // 找下一节起点
    let end = text.length;
    for (let j = i + 1; j < SECTION_DEFS.length; j++) {
      const nidx = text.indexOf(SECTION_DEFS[j].marker);
      if (nidx > idx) {
        end = nidx;
        break;
      }
    }
    const body = text.slice(bodyStart, end).trim();
    const isLast = end >= text.length;
    sections.push({
      key: def.key,
      label: def.label,
      title: extractTitle(body),
      rationale: extractRationale(body),
      details: extractDetails(body, ["为什么是它——"]),
      streaming: isLast,
    });
  }
  return { summary, sections };
}

/** 取理由行之后的内容作为 details */
function extractDetails(body: string, rationalePrefixes: string[]): string {
  const lines = body.split("\n");
  let rationaleLineIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (rationalePrefixes.some((p) => lines[i].trim().startsWith(p))) {
      rationaleLineIdx = i;
      break;
    }
  }
  if (rationaleLineIdx < 0) {
    // 没有理由行，返回去掉标题行后的全部
    return lines.filter((l) => !l.trim().startsWith("《")).join("\n").trim();
  }
  return lines.slice(rationaleLineIdx + 1).join("\n").trim();
}

// ────────────────────────────────────────
// 食材菜谱
// ────────────────────────────────────────
export function parseRecipe(text: string): Recipe {
  const title = extractTitle(text);
  const rationale = extractRationale(text);
  const ingredients: string[] = [];
  const steps: string[] = [];
  const tip = afterPrefix(text, /小贴士——\s*([^\n]*)/);

  let section: "none" | "ingredients" | "steps" = "none";
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (line.startsWith("食材——")) {
      section = "ingredients";
      continue;
    }
    if (line.startsWith("做法——")) {
      section = "steps";
      continue;
    }
    if (line.startsWith("小贴士——")) {
      section = "none";
      continue;
    }
    if (section === "ingredients" && line.startsWith("-")) {
      ingredients.push(line.replace(/^[-•]\s*/, "").trim());
    } else if (section === "steps" && /^\d+[.、)]/.test(line)) {
      steps.push(line.replace(/^\d+[.、)]\s*/, "").trim());
    }
  }
  return { title, rationale, ingredients, steps, tip };
}

// ────────────────────────────────────────
// 治愈方案
// ────────────────────────────────────────
const HEALING_DEFS = [
  { key: "song", label: "一首歌 · LISTEN", marker: "## 一首歌" },
  { key: "film", label: "一部影 · WATCH", marker: "## 一部影" },
  { key: "action", label: "一个小行动 · DO", marker: "## 一个小行动" },
] as const;

export function parseHealing(text: string): HealingPlan {
  const firstMark = HEALING_DEFS.map((d) => text.indexOf(d.marker)).filter((i) => i >= 0);
  const firstIdx = firstMark.length ? Math.min(...firstMark) : text.length;
  const comfort = text.slice(0, firstIdx).trim();

  const grab = (marker: string): { title: string; rationale: string } => {
    const idx = text.indexOf(marker);
    if (idx < 0) return { title: "", rationale: "" };
    const nlIdx = text.indexOf("\n", idx + marker.length);
    const bodyStart = nlIdx < 0 ? text.length : nlIdx + 1;
    const body = text.slice(bodyStart).trim();
    return { title: extractTitle(body), rationale: extractRationale(body) };
  };

  const song = grab(HEALING_DEFS[0].marker);
  const film = grab(HEALING_DEFS[1].marker);
  const actionDef = HEALING_DEFS[2];
  const aIdx = text.indexOf(actionDef.marker);
  let action = { title: "", rationale: "", details: "" };
  if (aIdx >= 0) {
    const nlIdx = text.indexOf("\n", aIdx + actionDef.marker.length);
    const bodyStart = nlIdx < 0 ? text.length : nlIdx + 1;
    const body = text.slice(bodyStart).trim();
    action = {
      title: extractTitle(body),
      rationale: extractRationale(body),
      details: extractDetails(body, ["为什么是它——"]),
    };
  }

  return { song, film, action: { title: action.title, rationale: action.rationale }, comfort };
}

/** 治愈方案里「小行动」的具体步骤 */
export function parseHealingActionDetails(text: string): string {
  const marker = "## 一个小行动";
  const idx = text.indexOf(marker);
  if (idx < 0) return "";
  const nlIdx = text.indexOf("\n", idx + marker.length);
  const bodyStart = nlIdx < 0 ? text.length : nlIdx + 1;
  const body = text.slice(bodyStart).trim();
  return extractDetails(body, ["为什么是它——"]);
}
