import { motion } from "framer-motion";
import Rule from "@/components/ui/Rule";
import StreamText from "@/components/ui/StreamText";
import SectionNumber from "@/components/ui/SectionNumber";
import type { HealingPlan } from "@/lib/types";
import type { StreamStatus } from "@/hooks/useStreamText";

interface HealingSpreadProps {
  plan: HealingPlan;
  actionDetails: string;
  status: StreamStatus;
  isMock: boolean;
}

function Block({
  num,
  label,
  title,
  rationale,
  details,
  streaming,
}: {
  num: string;
  label: string;
  title: string;
  rationale: string;
  details?: string;
  streaming?: boolean;
}) {
  return (
    <motion.article
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8, ease: [0.22, 0.61, 0.36, 1] }}
      className="grid grid-cols-12 gap-x-6 gap-y-3 py-7"
    >
      <header className="col-span-12 md:col-span-3">
        <SectionNumber num={num} label={label} />
      </header>
      <div className="col-span-12 md:col-span-9 md:pl-6 md:border-l md:border-rule">
        <h3 className="display-lg" style={{ lineHeight: 1.25 }}>
          {title ? (
            <>
              <span className="italic-accent mr-1" style={{ fontSize: "0.7em" }}>《</span>
              {title}
              <span className="italic-accent ml-1" style={{ fontSize: "0.7em" }}>》</span>
            </>
          ) : (
            streaming && <span className="caret" aria-hidden />
          )}
        </h3>
        {rationale && (
          <p className="prose-read !max-w-none mt-2">
            <StreamText text={rationale} streaming={streaming && !rationale} />
          </p>
        )}
        {details && (
          <div
            className="prose-read !max-w-none mt-3"
            style={{ whiteSpace: "pre-wrap" }}
          >
            <StreamText text={details} streaming={streaming && !details} />
          </div>
        )}
      </div>
    </motion.article>
  );
}

export default function HealingSpread({ plan, actionDetails, status, isMock }: HealingSpreadProps) {
  const streaming = status === "loading";
  const comfortStreaming = streaming && !plan.song.title;

  return (
    <motion.section initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.8 }} className="mt-12">
      <div className="flex items-center justify-between">
        <span className="label-cap">今晚的温柔 · A SOFT LANDING</span>
        {isMock && (
          <span className="label-cap" style={{ color: "var(--accent-ink)" }}>
            离线示例
          </span>
        )}
      </div>

      {/* 安抚话语：像一封信 */}
      {(plan.comfort || comfortStreaming) && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 1, delay: 0.1 }}
          className="mt-10 mb-6 mx-auto max-w-measure text-center"
        >
          <p
            style={{
              fontFamily: "var(--font-display)",
              fontSize: "clamp(1.25rem, 2.6vw, 1.6rem)",
              lineHeight: 1.9,
              color: "var(--ink)",
            }}
          >
            <StreamText text={plan.comfort} streaming={comfortStreaming} />
          </p>
        </motion.div>
      )}

      <Rule className="mt-12" />

      <Block num="01" label="一首歌 · LISTEN" title={plan.song.title} rationale={plan.song.rationale} streaming={streaming} />
      <Rule />
      <Block num="02" label="一部影 · WATCH" title={plan.film.title} rationale={plan.film.rationale} streaming={streaming} />
      <Rule />
      <Block
        num="03"
        label="一个小行动 · DO"
        title={plan.action.title}
        rationale={plan.action.rationale}
        details={actionDetails}
        streaming={streaming}
      />
      <Rule />
    </motion.section>
  );
}
