import Tag from "@/components/ui/Tag";
import type { MoodContext } from "@/lib/types";

interface ContextTagsProps {
  value: Pick<MoodContext, "alone" | "indoor" | "canCook">;
  onChange: (patch: Partial<Pick<MoodContext, "alone" | "indoor" | "canCook">>) => void;
}

interface TogglePairProps {
  label: string;
  left: string;
  right: string;
  state: boolean | undefined;
  onSet: (v: boolean | undefined) => void;
}

function TogglePair({ label, left, right, state, onSet }: TogglePairProps) {
  // state === true  → left active; === false → right active; undefined → none
  return (
    <div className="flex items-center gap-3">
      <span className="label-cap w-10 shrink-0">{label}</span>
      <Tag active={state === true} onClick={() => onSet(state === true ? undefined : true)}>
        {left}
      </Tag>
      <Tag active={state === false} onClick={() => onSet(state === false ? undefined : false)}>
        {right}
      </Tag>
    </div>
  );
}

export default function ContextTags({ value, onChange }: ContextTagsProps) {
  return (
    <div className="flex flex-wrap gap-x-8 gap-y-3">
      <TogglePair
        label="陪伴"
        left="一个人"
        right="有人陪"
        state={value.alone}
        onSet={(v) => onChange({ alone: v })}
      />
      <TogglePair
        label="场域"
        left="室内"
        right="愿出门"
        state={value.indoor}
        onSet={(v) => onChange({ indoor: v })}
      />
      <TogglePair
        label="炊事"
        left="能做饭"
        right="不便做"
        state={value.canCook}
        onSet={(v) => onChange({ canCook: v })}
      />
    </div>
  );
}
