import { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import Rule from "@/components/ui/Rule";
import HealingSpread from "@/components/healing/HealingSpread";
import { useStreamText } from "@/hooks/useStreamText";
import { useAccent } from "@/store/useAccent";
import { applyPalette, paletteForMood } from "@/lib/moodColor";
import { buildHealingMessages } from "@/lib/prompts";
import { mockHealingText } from "@/lib/mock";
import { parseHealing, parseHealingActionDetails } from "@/lib/parse";

// 治愈模式锁定暮粉色（温柔被抚慰）
const HEALING_PALETTE = paletteForMood(64);

export default function Healing() {
  const restorePalette = useAccent((s) => s.palette);
  const [feeling, setFeeling] = useState("");
  const [started, setStarted] = useState(false);

  const { text, status, isMock, run, reset } = useStreamText(
    () => buildHealingMessages(feeling),
    () => mockHealingText(),
    [feeling],
  );

  const plan = useMemo(() => parseHealing(text), [text]);
  const actionDetails = useMemo(() => parseHealingActionDetails(text), [text]);

  // 进入治愈页：锁定温柔色；离开：恢复用户心情色
  useEffect(() => {
    applyPalette(HEALING_PALETTE);
    return () => applyPalette(restorePalette);
  }, [restorePalette]);

  const handleStart = (text?: string) => {
    setFeeling(text ?? "");
    setStarted(true);
    setTimeout(() => run(), 0);
  };

  const handleReset = () => {
    reset();
    setStarted(false);
    setFeeling("");
  };

  return (
    <div className="flex flex-col">
      <span className="label-cap">治愈模式 · A SOFT LANDING</span>
      <h2 className="display-lg mt-3">今天有点累，没关系。</h2>
      <p className="prose-read mt-4 max-w-measure">
        不必振作，也不必把今晚过得有意义。调味师为你准备一首歌、一部影、一个小行动，和一段安抚的话语。
      </p>

      <Rule className="mt-10" />

      {!started ? (
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7 }}
          className="py-10"
        >
          <label className="label-cap" htmlFor="healing-text">
            如果愿意，说说哪里累（可选）
          </label>
          <textarea
            id="healing-text"
            value={feeling}
            onChange={(e) => setFeeling(e.target.value)}
            placeholder="比如：开了一天会，脑子嗡嗡的……"
            rows={2}
            className="input-line w-full mt-3 py-2 text-lg resize-none"
            style={{ fontFamily: "var(--font-display)", lineHeight: 1.7 }}
          />
          <div className="mt-8">
            <button type="button" className="btn-ink" onClick={() => handleStart(feeling)}>
              给我一点温柔
              <span className="italic-accent" style={{ fontSize: "0.8rem" }}>
                a soft landing
              </span>
            </button>
          </div>
        </motion.div>
      ) : (
        <div className="py-6 flex items-center justify-between">
          <span className="label-cap">{feeling ? `「${feeling}」` : "今晚的温柔"}</span>
          <button type="button" className="btn-ink" onClick={handleReset}>
            再静一会儿
          </button>
        </div>
      )}

      {started && (text || status === "loading") && (
        <HealingSpread plan={plan} actionDetails={actionDetails} status={status} isMock={isMock} />
      )}
    </div>
  );
}
