import { useCallback, useEffect, useRef, useState } from "react";
import { streamChat, hasLLM, type ChatMessage } from "@/lib/llm";
import { mockStream } from "@/lib/mock";

export type StreamStatus = "idle" | "loading" | "done" | "error";

export interface UseStreamTextResult {
  text: string;
  status: StreamStatus;
  isMock: boolean;
  run: () => void;
  abort: () => void;
  reset: () => void;
}

/**
 * 通用流式文本 hook。
 * - 有 LLM 配置则真实流式；失败回退 mock 流式。
 * - 无配置则直接 mock 流式。
 * - 离线/失败时 isMock=true，UI 标注「离线示例」。
 */
export function useStreamText(
  build: () => ChatMessage[] | null,
  mockText: () => string,
  deps: unknown[] = [],
): UseStreamTextResult {
  const [text, setText] = useState("");
  const [status, setStatus] = useState<StreamStatus>("idle");
  const [isMock, setIsMock] = useState(!hasLLM());
  const abortRef = useRef<AbortController | null>(null);
  const buildRef = useRef(build);
  const mockRef = useRef(mockText);
  buildRef.current = build;
  mockRef.current = mockText;

  const abort = useCallback(() => {
    abortRef.current?.abort();
  }, []);

  const reset = useCallback(() => {
    abortRef.current?.abort();
    setText("");
    setStatus("idle");
  }, []);

  const run = useCallback(async () => {
    abortRef.current?.abort();
    const ctrl = new AbortController();
    abortRef.current = ctrl;
    setText("");
    setStatus("loading");

    const messages = buildRef.current();
    if (!messages) {
      setStatus("idle");
      return;
    }

    const feed = async (gen: AsyncGenerator<string>, mock: boolean) => {
      setIsMock(mock);
      try {
        for await (const chunk of gen) {
          if (ctrl.signal.aborted) return;
          setText((prev) => prev + chunk);
        }
        if (!ctrl.signal.aborted) setStatus("done");
      } catch {
        if (ctrl.signal.aborted) return;
        // 真实流失败 → 回退 mock（仅当尚未回退过）
        if (!mock) {
          setStatus("loading");
          await feed(mockStream(mockRef.current(), ctrl.signal), true);
        } else {
          setStatus("error");
        }
      }
    };

    if (hasLLM()) {
      try {
        await feed(streamChat(messages, ctrl.signal), false);
      } catch {
        await feed(mockStream(mockRef.current(), ctrl.signal), true);
      }
    } else {
      await feed(mockStream(mockRef.current(), ctrl.signal), true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  useEffect(() => () => abortRef.current?.abort(), []);

  return { text, status, isMock, run, abort, reset };
}
