import { motion } from "framer-motion";
import SectionNumber from "@/components/ui/SectionNumber";
import Rationale from "./Rationale";
import StreamText from "@/components/ui/StreamText";
import type { PlanSection as PlanSectionData } from "@/lib/types";

const NUMS: Record<string, string> = {
  taste: "01",
  watch: "02",
  go: "03",
  rest: "04",
};

interface PlanSectionProps {
  data: PlanSectionData;
}

/** 单节：味 / 影 / 行 / 息 —— 编辑式版面，非卡片 */
export default function PlanSection({ data }: PlanSectionProps) {
  const { key, label, title, rationale, details, streaming } = data;
  const hasContent = title || rationale || details;
  if (!hasContent) return null;

  // 光标跟在「正在书写」的字段：最后一个有内容的字段
  const activeField: "title" | "rationale" | "details" = details
    ? "details"
    : rationale
      ? "rationale"
      : "title";

  return (
    <motion.article
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.7, ease: [0.22, 0.61, 0.36, 1] }}
      className="grid grid-cols-12 gap-x-6 gap-y-4 py-8"
    >
      {/* 左栏：编号 + 标签 */}
      <header className="col-span-12 md:col-span-3">
        <SectionNumber num={NUMS[key] ?? ""} label={label} />
      </header>

      {/* 右栏：标题 + 理由 + 内容 */}
      <div className="col-span-12 md:col-span-9 md:pl-6 md:border-l md:border-rule">
        <h3 className="display-lg" style={{ lineHeight: 1.25 }}>
          {title && (
            <>
              <span className="italic-accent mr-1" style={{ fontSize: "0.7em" }}>《</span>
              {title}
              <span className="italic-accent ml-1" style={{ fontSize: "0.7em" }}>》</span>
            </>
          )}
          {!title && streaming && <span className="caret" aria-hidden />}
          {title && streaming && activeField === "title" && (
            <span className="caret" aria-hidden />
          )}
        </h3>

        {(rationale || (streaming && activeField === "rationale")) && (
          <Rationale text={rationale} streaming={streaming && activeField === "rationale"} />
        )}

        {(details || (streaming && activeField === "details")) && (
          <div
            className="prose-read !max-w-none mt-3"
            style={{ whiteSpace: "pre-wrap" }}
          >
            <StreamText text={details} streaming={streaming && activeField === "details"} />
          </div>
        )}
      </div>
    </motion.article>
  );
}
