import { useMemo, useState } from "react";
import { motion } from "framer-motion";
import FridgeInput from "@/components/fridge/FridgeInput";
import RecipeView from "@/components/fridge/RecipeView";
import Rule from "@/components/ui/Rule";
import { useStreamText } from "@/hooks/useStreamText";
import { buildFridgeMessages } from "@/lib/prompts";
import { mockFridgeText } from "@/lib/mock";
import { parseRecipe } from "@/lib/parse";

interface FridgeOpts {
  preference?: string;
  minutes?: number;
  level?: string;
}

export default function Fridge() {
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [opts, setOpts] = useState<FridgeOpts>({});
  const [submitted, setSubmitted] = useState(false);

  const { text, status, isMock, run, reset } = useStreamText(
    () =>
      ingredients.length
        ? buildFridgeMessages(ingredients, opts)
        : null,
    () => mockFridgeText(ingredients),
    [ingredients, opts],
  );

  const recipe = useMemo(() => parseRecipe(text), [text]);

  const handleSubmit = (ings: string[], o: FridgeOpts) => {
    setIngredients(ings);
    setOpts(o);
    setSubmitted(true);
    setTimeout(() => run(), 0);
  };

  const handleReset = () => {
    reset();
    setSubmitted(false);
  };

  return (
    <div className="flex flex-col">
      <span className="label-cap">食材配菜 · FROM THE FRIDGE</span>
      <h2 className="display-lg mt-3">冰箱里有什么，就过什么日子</h2>
      <p className="prose-read mt-4 max-w-measure">
        把冰箱里的食材交给调味师，它配一道真实可做的菜，并告诉你「为什么用它」。
      </p>

      <Rule className="mt-10" />

      {!submitted ? (
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="py-10"
        >
          <FridgeInput onSubmit={handleSubmit} loading={false} />
        </motion.div>
      ) : (
        <div className="py-6 flex items-center justify-between">
          <span className="label-cap">{ingredients.join("、")}</span>
          <button type="button" className="btn-ink" onClick={handleReset}>
            换一组食材
          </button>
        </div>
      )}

      {submitted && (text || status === "loading") && (
        <RecipeView recipe={recipe} rawText={text} status={status} isMock={isMock} />
      )}
    </div>
  );
}
