import Rule from "@/components/ui/Rule";
import type { MoodEntry } from "@/lib/types";

interface MoodTimelineProps {
  entries: MoodEntry[];
}

const WEEKDAY = ["日", "一", "二", "三", "四", "五", "六"];

export default function MoodTimeline({ entries }: MoodTimelineProps) {
  const sorted = [...entries].sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div>
      {sorted.map((e, i) => {
        const d = new Date(e.date);
        return (
          <div key={e.id}>
            {i > 0 && <Rule />}
            <article className="grid grid-cols-12 gap-x-6 py-6">
              {/* 左：日期 + 色点 */}
              <div className="col-span-12 md:col-span-3 flex md:flex-col gap-3 md:gap-1 items-baseline md:items-start">
                <span
                  className="inline-block w-2 h-2 rounded-full"
                  style={{ background: e.accent, marginTop: 6 }}
                />
                <div>
                  <div
                    className="text-base"
                    style={{ fontFamily: "var(--font-display)", fontWeight: 500 }}
                  >
                    {d.getMonth() + 1}月{d.getDate()}日
                  </div>
                  <div className="label-cap mt-1">周{WEEKDAY[d.getDay()]}</div>
                </div>
              </div>
              {/* 右：心情 + 总结 */}
              <div className="col-span-12 md:col-span-9 md:pl-6 md:border-l md:border-rule">
                {e.moodText && (
                  <p style={{ fontFamily: "var(--font-display)", color: "var(--ink)", fontSize: "1.05rem", lineHeight: 1.7 }}>
                    「{e.moodText}」
                  </p>
                )}
                {e.summary && (
                  <p className="prose-read !max-w-none mt-2 text-ink-mute">{e.summary}</p>
                )}
              </div>
            </article>
          </div>
        );
      })}
    </div>
  );
}
