import type { MoodEntry } from "./types";

const KEY = "mood-seasoner:history:v1";

export function loadHistory(): MoodEntry[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw) as MoodEntry[];
    if (!Array.isArray(arr)) return [];
    return arr;
  } catch {
    return [];
  }
}

export function saveEntry(entry: MoodEntry): MoodEntry[] {
  const list = loadHistory();
  // 同一天覆盖（按日期字符串）
  const day = entry.date.slice(0, 10);
  const filtered = list.filter((e) => !e.date.startsWith(day));
  const next = [entry, ...filtered].slice(0, 60);
  try {
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
    // 容量满，静默
  }
  return next;
}

export function clearHistory(): void {
  try {
    localStorage.removeItem(KEY);
  } catch {
    // ignore
  }
}
