import { useState } from "react";
import type { MoodEntry } from "@/lib/types";

interface MoodCurveProps {
  entries: MoodEntry[];
}

const W = 800;
const H = 220;
const PAD_X = 48;
const PAD_Y = 40;

export default function MoodCurve({ entries }: MoodCurveProps) {
  const [hover, setHover] = useState<number | null>(null);

  const sorted = [...entries].sort((a, b) => a.date.localeCompare(b.date));
  if (sorted.length === 0) return null;

  const n = sorted.length;
  const xAt = (i: number) =>
    n === 1 ? W / 2 : PAD_X + (i / (n - 1)) * (W - 2 * PAD_X);
  const yAt = (v: number) => H - PAD_Y - (v / 100) * (H - 2 * PAD_Y);

  const points = sorted.map((e, i) => `${xAt(i)},${yAt(e.moodValue)}`);
  const polyline = points.join(" ");

  return (
    <div className="w-full overflow-x-auto">
      <svg viewBox={`0 0 ${W} ${H}`} className="w-full min-w-[560px]" style={{ height: "auto" }}>
        {/* 基线 + 顶线 */}
        <line x1={PAD_X} y1={H - PAD_Y} x2={W - PAD_X} y2={H - PAD_Y} stroke="var(--rule)" strokeWidth="1" />
        <line x1={PAD_X} y1={PAD_Y} x2={W - PAD_X} y2={PAD_Y} stroke="var(--rule)" strokeWidth="1" strokeDasharray="2 4" />
        {/* 纵轴标签 */}
        <text x={PAD_X - 10} y={PAD_Y + 4} textAnchor="end" className="label-cap" fontSize="9" fill="var(--ink-mute)">喜悦</text>
        <text x={PAD_X - 10} y={H - PAD_Y + 4} textAnchor="end" className="label-cap" fontSize="9" fill="var(--ink-mute)">低落</text>

        {n >= 2 && (
          <polyline
            points={polyline}
            fill="none"
            stroke="var(--accent)"
            strokeWidth="1.5"
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        )}

        {sorted.map((e, i) => (
          <g key={e.id} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
            <circle
              cx={xAt(i)}
              cy={yAt(e.moodValue)}
              r={hover === i ? 5 : 3.5}
              fill={e.accent}
              stroke="var(--paper)"
              strokeWidth="1.5"
              style={{ transition: "r 200ms" }}
            />
            {/* 日期标签 */}
            <text
              x={xAt(i)}
              y={H - PAD_Y + 16}
              textAnchor="middle"
              fontSize="9"
              fill="var(--ink-mute)"
              style={{ letterSpacing: "0.05em" }}
            >
              {fmtDay(e.date)}
            </text>
            {hover === i && (
              <g>
                <rect
                  x={xAt(i) - 60}
                  y={yAt(e.moodValue) - 48}
                  width="120"
                  height="34"
                  fill="var(--paper-deep)"
                  stroke="var(--rule)"
                />
                <text x={xAt(i)} y={yAt(e.moodValue) - 32} textAnchor="middle" fontSize="9.5" fill="var(--ink)">
                  {e.summary ? truncate(e.summary, 14) : e.moodText ? truncate(e.moodText, 14) : "—"}
                </text>
                <text x={xAt(i)} y={yAt(e.moodValue) - 20} textAnchor="middle" fontSize="8" fill="var(--ink-mute)">
                  {fmtFull(e.date)}
                </text>
              </g>
            )}
          </g>
        ))}
      </svg>
    </div>
  );
}

function fmtDay(iso: string): string {
  const d = new Date(iso);
  return `${d.getMonth() + 1}/${d.getDate()}`;
}
function fmtFull(iso: string): string {
  const d = new Date(iso);
  return `${d.getMonth() + 1}月${d.getDate()}日`;
}
function truncate(s: string, n: number): string {
  return s.length > n ? s.slice(0, n) + "…" : s;
}
