import { create } from "zustand";
import { paletteForMood, applyPalette, type MoodPalette } from "@/lib/moodColor";

interface AccentState {
  moodValue: number;
  palette: MoodPalette;
  setMood: (v: number) => void;
}

const initial = paletteForMood(58);
applyPalette(initial);

export const useAccent = create<AccentState>((set) => ({
  moodValue: 58,
  palette: initial,
  setMood: (v) => {
    const palette = paletteForMood(v);
    applyPalette(palette);
    set({ moodValue: v, palette });
  },
}));
